DROP TABLE IF EXISTS `emp_tbl_main`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `emp_tbl_main` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `emp_id` varchar(15) NOT NULL,
  `name_bangla` varchar(255) NOT NULL,
  `designation_bangla` varchar(255) DEFAULT NULL,
  `office` varchar(100) DEFAULT NULL,
  `phone_office` varchar(50) DEFAULT NULL,
  `intercom` varchar(20) DEFAULT NULL,
  `mobile` varchar(20) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `department` varchar(255) DEFAULT NULL,
  `division` varchar(255) DEFAULT NULL,
  `image` varchar(255) NOT NULL,
  `fax` varchar(50) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_emp_email` (`email`),
  KEY `idx_emp_mobile` (`mobile`),
  KEY `idx_emp_designation` (`designation_bangla`),
  KEY `idx_emp_intercom` (`intercom`)
) ENGINE=InnoDB AUTO_INCREMENT=233 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

